import fs from 'node:fs'
import path from 'node:path'

const ROOT = process.cwd()
const QUESTIONS_DIR = path.join(ROOT, 'src', 'data', 'questions')

const FULL_PLACEHOLDER = 'Подробный ответ пока не добавлен.'
const SHORT_PLACEHOLDER = 'Краткий ответ пока не добавлен.'

const clean = (s) => s.toLowerCase().replace(/ё/g, 'е')
const esc = (s) => String(s)
  .replace(/\\/g, '\\\\')
  .replace(/`/g, '\\`')
  .replace(/\$\{/g, '\\${')

const stripMd = (s) => String(s)
  .replace(/```[\s\S]*?```/g, ' ')
  .replace(/`([^`]+)`/g, '$1')
  .replace(/!\[[^\]]*\]\([^)]*\)/g, ' ')
  .replace(/\[([^\]]+)\]\([^)]*\)/g, '$1')
  .replace(/^#{1,6}\s+/gm, '')
  .replace(/\*\*([^*]+)\*\*/g, '$1')
  .replace(/\*([^*]+)\*/g, '$1')
  .replace(/^[-*+]\s+/gm, '')
  .replace(/^\d+\.\s+/gm, '')
  .replace(/\s+/g, ' ')
  .trim()

function sentenceShort(full, title) {
  const interview = full.match(/Для собеседования:?\*{0,2}\s*([^\n]+)/i)
  if (interview?.[1]) return stripMd(interview[1]).slice(0, 650)

  const text = stripMd(full)
  const sentences = text.match(/[^.!?]+[.!?]+/g) || [text]
  const candidate = sentences.slice(0, 2).join(' ').trim()
  if (candidate.length >= 70) return candidate.slice(0, 650)
  return `${title.replace(/[?.]+$/, '')}: ${candidate}`.slice(0, 650)
}

function md(title, summary, bullets = [], code = '', note = '') {
  const parts = [`## ${title}`, '', summary.trim()]
  if (bullets.length) {
    parts.push('', '**Ключевые моменты:**')
    for (const b of bullets) parts.push(`- ${b}`)
  }
  if (code) parts.push('', '**Пример:**', '', code.trim())
  if (note) parts.push('', `**На практике:** ${note.trim()}`)
  return parts.join('\n')
}

const contains = (q, ...xs) => xs.some(x => clean(q).includes(clean(x)))

function pinia(q) {
  if (contains(q, 'реактивность внутри pinia')) return md('Реактивность в Pinia',
    'Pinia построена поверх реактивности Vue. State в store становится реактивным, getters работают как вычисляемые значения, а actions изменяют состояние обычными присваиваниями. Компоненты, которые читают state/getters, автоматически обновляются при изменениях.',
    ['В Setup Store обычно используются `ref`, `reactive` и `computed`.', 'При деструктуризации state/getters используют `storeToRefs()`, иначе можно потерять реактивную связь.', 'Actions можно вызывать напрямую; отдельного слоя mutations, как во Vuex, нет.', 'Подписки `$subscribe()` позволяют наблюдать изменения state.'],
    '```ts\nconst useCounter = defineStore("counter", () => {\n  const count = ref(0)\n  const double = computed(() => count.value * 2)\n  const increment = () => count.value++\n  return { count, double, increment }\n})\n```')
  if (contains(q, 'персистентность state')) return md('Персистентность Pinia state',
    'Pinia сама по себе не сохраняет state после перезагрузки страницы. Для этого состояние сериализуют в localStorage/sessionStorage либо используют плагин наподобие `pinia-plugin-persistedstate`.',
    ['Сохраняйте только действительно нужные поля: токены и чувствительные данные требуют отдельной оценки безопасности.', 'При SSR доступ к `window/localStorage` возможен только на клиенте.', 'Нужно продумать версионирование persisted state и миграции при изменении структуры.'],
    '```ts\nexport const useSettings = defineStore("settings", {\n  state: () => ({ theme: "light" }),\n  persist: true,\n})\n```')
  if (contains(q, 'собственный pinia plugin')) return md('Собственный Pinia plugin',
    'Pinia-плагин — функция, подключаемая через `pinia.use()`. Она вызывается для каждого создаваемого store и получает контекст с `store`, `pinia`, `app` и options. Плагин может добавлять свойства, подписки, persistence, логирование или общую инфраструктуру.',
    ['Возвращённые из plugin свойства добавляются в каждый store.', 'Подписки, созданные плагином, стоит корректно очищать.', 'Для TypeScript дополнительные свойства расширяют через module augmentation.'],
    '```ts\nconst pinia = createPinia()\npinia.use(({ store }) => {\n  store.$subscribe((_mutation, state) => {\n    console.log(store.$id, state)\n  })\n})\n```')
  if (contains(q, 'вне компонента', 'ssr')) return md('Pinia вне компонентов и SSR',
    'Внутри `setup()` активный экземпляр Pinia определяется автоматически. Вне component setup, особенно при SSR, лучше явно передавать экземпляр Pinia в `useStore(pinia)`, чтобы запросы разных пользователей не разделяли состояние.',
    ['На сервере создавайте новый Pinia для каждого запроса.', 'Не храните server-side store в глобальном singleton.', 'В router guards после установки Pinia можно получать store с явным `pinia`.'],
    '```ts\nconst pinia = createPinia()\napp.use(pinia)\nconst user = useUserStore(pinia)\n```')
  if (contains(q, 'accepthmrupdate')) return md('acceptHMRUpdate',
    '`acceptHMRUpdate()` помогает store поддерживать Hot Module Replacement: при изменении кода store во время разработки Pinia обновляет его определение без полной перезагрузки страницы и, насколько возможно, сохраняет текущее состояние.',
    ['Используется только в dev/HMR-коде.', 'Типичный вызов помещают рядом с `defineStore`.', 'Это улучшает DX, но не влияет на production runtime.'],
    '```ts\nif (import.meta.hot) {\n  import.meta.hot.accept(acceptHMRUpdate(useUserStore, import.meta.hot))\n}\n```')
  if (contains(q, 'feature-based')) return md('Структура Pinia stores в большом проекте',
    'В крупном приложении store удобнее группировать по бизнес-фичам, а не складывать все store в одну общую папку без контекста. Store должен владеть состоянием конкретной области и предоставлять понятный публичный API.',
    ['Не делайте один «god store».', 'Разделяйте server state и чисто UI state.', 'Переиспользуемую логику выносите в composables/services.', 'Избегайте циклических зависимостей между stores.'])
  if (contains(q, 'глобальные', 'getters', 'ошибки в actions')) return md('Общие getters и обработка ошибок',
    'В Pinia нет специального понятия root getters как во Vuex. Общую вычисляемую логику обычно оформляют отдельным store или composable, а один store может использовать другой внутри getter/action.',
    ['Ошибки в actions можно пробрасывать вызывающему коду либо нормализовать в одном месте.', 'Для глобального логирования действий используют `$onAction()` или plugin.', 'Не скрывайте ошибку без изменения состояния loading/error.'],
    '```ts\nasync function load() {\n  this.loading = true\n  try { this.data = await api.get() }\n  catch (e) { this.error = normalizeError(e); throw e }\n  finally { this.loading = false }\n}\n```')
  if (contains(q, '$dispose', 'testingpinia')) return md('$dispose и тестирование stores',
    '`store.$dispose()` останавливает effect scope store и удаляет его из реестра Pinia; это полезно для динамически живущих stores и тестов. Для component tests часто применяют `createTestingPinia`, который позволяет контролировать actions и начальный state.',
    ['Для unit-теста самого store можно создать обычный `createPinia()` и `setActivePinia()`.', '`createTestingPinia` удобен для тестов компонентов, где actions часто стабят.', 'После тестов важно изолировать Pinia между test cases.'])
  if (contains(q, 'vue devtools', 'micro-frontends')) return md('Devtools и shared state между micro-frontends',
    'Pinia интегрируется с Vue Devtools и показывает stores, state и изменения. Для micro-frontends общий Pinia singleton возможен только если части приложения действительно разделяют один Vue runtime и lifecycle; иначе надёжнее синхронизировать состояние через явный контракт.',
    ['Варианты контракта: события, shared package, URL, browser storage, BroadcastChannel или backend.', 'Не связывайте независимые micro-frontends внутренней структурой чужого store.', 'Версионируйте общий контракт.'])
  if (contains(q, 'мигрировать с vuex')) return md('Миграция Vuex → Pinia',
    'Обычно мигрируют по одному Vuex module: state переносится в state/ref, getters — в getters/computed, actions — в actions/functions, а mutations исчезают, потому что Pinia разрешает изменять state непосредственно или через actions.',
    ['Сначала перенесите leaf modules с минимумом зависимостей.', 'Замените map helpers на прямой store и `storeToRefs`.', 'Pinia обычно даёт меньше boilerplate; реальная производительность чаще зависит от архитектуры и объёма реактивного state, а не от названия библиотеки.'])
  return md('Vuex rootState/rootGetters и динамические модули',
    'Во Vuex action/getter может получать доступ к корневому состоянию и корневым getters через `rootState` и `rootGetters`. Namespaced module при необходимости вызывает root action/getter с `{ root: true }`. Динамические модули подключают через `store.registerModule()` и удаляют через `unregisterModule()`.',
    ['Динамические модули полезны для lazy-loaded features.', 'Следите за namespace и жизненным циклом регистрации.', 'В Pinia аналог обычно достигается отдельными stores без отдельной регистрации module tree.'])
}

function nodeAnswer(q) {
  return md('Query-параметры и body parser',
    'Query-параметры — часть URL после `?`, например `/users?page=2&active=true`. В Express они доступны в `req.query`. Тело запроса приходит отдельно и для JSON разбирается middleware `express.json()`; для HTML form-urlencoded — `express.urlencoded()`.',
    ['Query подходит для фильтрации, сортировки и пагинации.', 'Body используют для данных создаваемого/изменяемого ресурса.', 'Всегда валидируйте и приводите типы: значения из query обычно приходят строками.', 'Ограничивайте размер body и не доверяйте входным данным.'],
    '```js\napp.use(express.json())\napp.get("/users", (req, res) => {\n  const page = Number(req.query.page ?? 1)\n  res.json({ page })\n})\napp.post("/users", (req, res) => res.json(req.body))\n```')
}

function sql(q) {
  if (contains(q, 'индексы')) return md('Индексы', 'Индекс — дополнительная структура данных, ускоряющая поиск строк по определённым столбцам ценой дополнительной памяти и более дорогих INSERT/UPDATE/DELETE.', ['Индекс полезен для селективных `WHERE`, JOIN и иногда ORDER BY.', 'Слишком много индексов замедляют запись и требуют места.', 'Составной индекс учитывает порядок столбцов.', 'Проверяйте использование через план запроса, а не добавляйте индексы «на всякий случай».'], '```sql\nCREATE INDEX idx_users_email ON users(email);\n```')
  if (contains(q, 'begin', 'commit', 'rollback')) return md('Транзакции', 'Транзакция объединяет несколько операций в одну логическую единицу. `BEGIN` начинает транзакцию, `COMMIT` фиксирует изменения, `ROLLBACK` отменяет незакоммиченные изменения.', ['Транзакции защищают инварианты данных.', 'Держите транзакции короткими, чтобы уменьшить блокировки и конфликты.', 'Ошибку внутри бизнес-операции обычно сопровождают rollback.'], '```sql\nBEGIN;\nUPDATE accounts SET balance = balance - 100 WHERE id = 1;\nUPDATE accounts SET balance = balance + 100 WHERE id = 2;\nCOMMIT;\n```')
  if (contains(q, 'нормализация')) return md('Нормализация 1NF–3NF', 'Нормализация уменьшает дублирование данных и аномалии обновления за счёт разбиения данных на связанные таблицы.', ['1NF: атомарные значения и отсутствие повторяющихся групп.', '2NF: 1NF + неключевые атрибуты зависят от всего составного ключа.', '3NF: 2NF + нет транзитивной зависимости неключевых атрибутов от ключа.', 'В аналитике или ради производительности иногда осознанно денормализуют.'])
  if (contains(q, 'ddl', 'dml', 'dcl')) return md('DDL, DML, DCL и DELETE/TRUNCATE/DROP', 'DDL меняет структуру схемы (`CREATE`, `ALTER`, `DROP`), DML работает с данными (`SELECT`, `INSERT`, `UPDATE`, `DELETE`), DCL управляет доступом (`GRANT`, `REVOKE`).', ['`DELETE` удаляет выбранные строки и поддерживает `WHERE`.', '`TRUNCATE` быстро очищает таблицу целиком и обычно работает как DDL-подобная операция.', '`DROP` удаляет сам объект таблицы вместе с его определением.'])
  if (contains(q, 'view', 'coalesce', 'window')) return md('VIEW, CASE, COALESCE, EXISTS и window functions', 'Это разные инструменты SQL для повторного использования запросов и выразительной обработки данных.', ['VIEW сохраняет определение запроса как виртуальную таблицу.', '`CASE` реализует условную логику, `COALESCE` берёт первое не-NULL значение.', '`EXISTS` проверяет наличие строк; часто удобен для коррелированных подзапросов.', '`IN` удобен для небольшого набора/подзапроса, а оптимизатор нередко преобразует оба варианта.', 'Window functions (`ROW_NUMBER`, `SUM() OVER`) считают значения по окну, не схлопывая строки как GROUP BY.'])
  if (contains(q, 'acid')) return md('ACID и уровни изоляции', 'ACID описывает свойства надёжной транзакции: Atomicity, Consistency, Isolation, Durability.', ['Atomicity — все операции либо применены, либо нет.', 'Consistency — после commit сохраняются ограничения и инварианты.', 'Isolation — параллельные транзакции контролируемо взаимодействуют.', 'Durability — подтверждённые изменения переживают сбой.', 'Стандартные уровни: Read Uncommitted, Read Committed, Repeatable Read, Serializable; конкретные гарантии зависят от СУБД.'])
  if (contains(q, 'dirty read', 'phantom')) return md('Аномалии изоляции', 'Dirty Read — чтение незакоммиченных данных; Non-repeatable Read — повторное чтение той же строки даёт другое значение; Phantom Read — повторный запрос по условию видит новый/исчезнувший набор строк.', ['Более строгая изоляция снижает количество аномалий, но может повышать стоимость конкурентного доступа.', 'MVCC и блокировки реализуют эти гарантии по-разному в разных СУБД.'])
  if (contains(q, 'mvcc', 'explain analyze')) return md('MVCC и EXPLAIN ANALYZE', 'MVCC хранит несколько версий строк, чтобы чтения видели согласованный snapshot и меньше конфликтовали с записью. `EXPLAIN` показывает план выполнения, а `EXPLAIN ANALYZE` ещё и реально выполняет запрос, показывая фактические времена и количество строк.', ['Сравнивайте estimated rows с actual rows.', 'Ищите дорогие scan/join/sort узлы.', 'Помните: `EXPLAIN ANALYZE` выполняет запрос, поэтому с изменяющими запросами используйте осторожно.'])
  if (contains(q, 'seq scan', 'index scan')) return md('Seq Scan vs Index Scan', 'Seq Scan последовательно читает таблицу и выгоден, когда нужно значительное количество строк. Index Scan сначала использует индекс и выгоден для селективного условия, но добавляет случайные обращения к данным.', ['Index-only scan может получить данные из самого индекса, если нужные столбцы покрыты и видимость позволяет.', 'Оптимизатор выбирает план по статистике и стоимости; наличие индекса не гарантирует его использование.'])
  if (contains(q, 'партиционирование', 'шардирование', 'репликация')) return md('Partitioning, sharding и replication', 'Партиционирование делит одну логическую таблицу на части внутри СУБД; шардирование распределяет данные между независимыми узлами; репликация хранит копии данных для высокой доступности и/или масштабирования чтения.', ['Partitioning упрощает работу с большими диапазонами и lifecycle данных.', 'Sharding требует ключа распределения и усложняет cross-shard операции.', 'Primary/replica репликация обычно направляет запись на primary, а чтения можно распределять.', 'Multi-primary даёт запись в нескольких местах, но требует разрешения конфликтов.'])
  if (contains(q, 'материализованные', 'cte')) return md('Materialized View и CTE', 'Обычный CTE (`WITH`) даёт имя промежуточному запросу и повышает читаемость; recursive CTE позволяет рекурсивно обходить иерархии/графы. Materialized view физически сохраняет результат запроса и требует refresh для обновления.', ['Materialized view ускоряет дорогие повторяющиеся чтения ценой устаревания данных.', 'CTE не является автоматическим кэшем результата.', 'Recursive CTE состоит из anchor части и рекурсивной части.'])
  if (contains(q, 'lateral', 'full-text', 'json/jsonb')) return md('LATERAL, full-text search и JSON/JSONB', '`LATERAL` позволяет подзапросу в FROM ссылаться на строки предыдущих элементов FROM. Full-text search использует специализированные структуры для поиска по словам. JSON/JSONB позволяют хранить полуструктурированные данные.', ['В PostgreSQL JSONB хранится в бинарно разобранном виде и поддерживает эффективные индексы.', 'LATERAL полезен, например, для top-N записей для каждой строки.', 'Для сложного полнотекстового поиска часто создают специальный индекс.'])
  if (contains(q, 'триггеры', 'stored procedures', 'курсоры')) return md('Triggers, stored procedures и cursors', 'Trigger автоматически запускает серверную логику на событие таблицы; stored procedure/function переносит часть логики на сервер БД; cursor позволяет пошагово обходить большой result set.', ['Триггеры полезны для аудита и инвариантов, но скрытая логика усложняет отладку.', 'Процедуры уменьшают сетевые round trips, но усиливают привязку к СУБД.', 'Курсор полезен, когда результат нельзя удобно обработать целиком.'])
  if (contains(q, 'deadlock')) return md('Deadlock', 'Deadlock возникает, когда транзакции циклически ждут блокировки друг друга. СУБД обнаруживает цикл и откатывает одну из транзакций.', ['Берите блокировки в одинаковом порядке.', 'Делайте транзакции короткими.', 'Используйте подходящие индексы, чтобы блокировать меньше строк.', 'На уровне приложения будьте готовы повторить транзакцию после deadlock.'])
  return md('Connection pooling и оптимизация запросов', 'Connection pool переиспользует ограниченное число соединений с БД вместо дорогого создания соединения на каждый запрос. Query optimization начинается с измерений и плана выполнения.', ['Настройте размер pool под возможности БД, а не под число HTTP-запросов.', 'Используйте `EXPLAIN (ANALYZE)` и реальные метрики.', 'Выбирайте только нужные столбцы/строки, устраняйте N+1, добавляйте обоснованные индексы.', 'Следите за lock waits, slow queries и статистикой.'])
}

function postgres(q) {
  if (contains(q, 'grant', 'revoke', 'пользователи')) return md('Пользователи и права', '`GRANT` выдаёт привилегии, а `REVOKE` отзывает их. В PostgreSQL пользователи и группы представлены ролями; права можно выдавать на database, schema, table, sequence и другие объекты.', ['Следуйте least privilege.', 'Удобно выдавать права групповой роли, а пользователям — membership.', 'Не используйте superuser для приложения.'], '```sql\nGRANT SELECT, INSERT ON TABLE orders TO app_role;\nREVOKE DELETE ON TABLE orders FROM app_role;\n```')
  if (contains(q, 'schema', 'tablespace', 'sequence')) return md('Schema, tablespace, sequence, materialized view, enum', 'Schema — namespace объектов внутри БД; tablespace определяет физическое размещение объектов; sequence генерирует числовую последовательность; materialized view хранит результат запроса; enum задаёт ограниченный набор значений.', ['Schema помогает разделять объекты и права.', 'Sequence часто используется для идентификаторов.', 'Materialized view нужно refresh-ить.', 'Enum удобен для стабильных наборов, но изменение модели требует миграций.'])
  if (contains(q, 'b-tree', 'gin', 'gist')) return md('Типы индексов PostgreSQL', 'B-tree — универсальный индекс для равенства, диапазонов и сортировки. Hash ориентирован на равенство. GIN хорошо подходит для многозначных данных (arrays, JSONB, full-text). GiST — обобщённая структура для геоданных, ranges и других операторных классов.', ['Выбирайте тип по операциям, а не только по типу столбца.', 'GIN обычно дороже при записи, но силён при contains/search.', 'Проверяйте конкретный operator class.'])
  if (contains(q, 'partial index', 'covering')) return md('Partial, composite и covering indexes', 'Partial index индексирует только строки, удовлетворяющие условию. Composite index содержит несколько столбцов. Covering index включает все данные, необходимые типичному запросу, и может позволить index-only scan.', ['Порядок столбцов composite index критичен.', 'Partial index полезен для небольшой «активной» части таблицы.', '`INCLUDE` позволяет добавить столбцы в PostgreSQL без включения их в search key.'])
  if (contains(q, 'concurrently')) return md('CREATE INDEX CONCURRENTLY', '`CREATE INDEX CONCURRENTLY` создаёт индекс в PostgreSQL с существенно меньшей блокировкой обычных операций записи, поэтому подходит для production-таблиц.', ['Операция обычно дольше и выполняет несколько проходов.', 'Нельзя запускать внутри обычного transaction block.', 'При ошибке может остаться INVALID index, который нужно удалить/пересоздать.'])
  if (contains(q, 'vacuum', 'dead tuples', 'bloat')) return md('VACUUM и autovacuum', 'Из-за MVCC UPDATE/DELETE оставляют старые версии строк (dead tuples). VACUUM делает это место повторно используемым и обслуживает visibility/freeze metadata; autovacuum выполняет обслуживание автоматически.', ['Обычный VACUUM не «сжимает» файл таблицы до минимального размера.', '`VACUUM FULL` переписывает таблицу и требует более сильной блокировки.', 'Плохие настройки autovacuum и длинные транзакции могут приводить к bloat.'])
  if (contains(q, 'pgbouncer')) return md('PgBouncer', 'PgBouncer — лёгкий connection pooler перед PostgreSQL. Он уменьшает число реальных server connections и стоимость их создания.', ['Session pooling закрепляет соединение за клиентом на сессию.', 'Transaction pooling возвращает соединение в pool после каждой транзакции и масштабируется лучше, но несовместим с частью session-level state.', 'Размер pool должен учитывать лимиты PostgreSQL и workload.'])
  if (contains(q, 'репликация')) return md('Репликация PostgreSQL', 'Physical/streaming replication передаёт изменения на уровне WAL и обычно используется для standby. Logical replication передаёт логические изменения выбранных таблиц и удобна для интеграций и некоторых миграций.', ['Failover переключает трафик на реплику при проблеме primary.', 'Patroni автоматизирует HA-оркестрацию PostgreSQL с распределённым consensus store.', 'Репликация не заменяет backup: ошибки пользователя могут реплицироваться.'])
  if (contains(q, 'pg_stat_statements', 'pgbadger')) return md('Мониторинг PostgreSQL', '`pg_stat_statements` агрегирует статистику выполнения нормализованных SQL-запросов: calls, total/mean time, rows и др. pgBadger анализирует PostgreSQL logs и строит отчёты.', ['Ищите запросы с большим total time и высокой latency.', 'Сопоставляйте SQL-статистику с CPU, I/O, locks и connection metrics.', 'Для проблемного запроса изучайте `EXPLAIN (ANALYZE, BUFFERS)`.'])
  return md('Partitioning: range, list, hash', 'Declarative partitioning делит таблицу на дочерние partitions по ключу. Range — по диапазонам, List — по перечисленным значениям, Hash — по хэшу ключа.', ['Partition pruning позволяет не читать нерелевантные partitions.', 'Partitioning не является автоматическим ускорителем всех запросов.', 'Продумайте число partitions и операции lifecycle/retention.'])
}

function redis(q) {
  if (contains(q, 'eviction')) return md('Redis eviction policies', 'При достижении `maxmemory` Redis действует согласно eviction policy. `noeviction` отказывает новым write-командам, а политики LRU/LFU/random/TTL удаляют ключи по выбранной стратегии.', ['`allkeys-lru` — кандидаты из всех ключей по принципу least recently used.', '`allkeys-lfu` — least frequently used.', '`volatile-*` рассматривает ключи с TTL.', 'Политику выбирают исходя из того, является Redis кэшем или источником критичных данных.'])
  if (contains(q, 'rdb', 'aof')) return md('RDB vs AOF', 'RDB периодически создаёт компактный snapshot набора данных. AOF журналирует операции записи и при старте воспроизводит их. Можно использовать один режим, оба или отключить persistence.', ['RDB компактнее и удобен для backup, но между snapshots возможна большая потеря последних изменений.', 'AOF обычно даёт меньший RPO при подходящей fsync-политике, но файл/запись дороже.', 'Выбор зависит от допустимой потери данных и latency.'])
  if (contains(q, 'sentinel', 'cluster')) return md('Redis Sentinel и Cluster', 'Sentinel обеспечивает мониторинг и автоматический failover primary/replica для не-шардированного Redis. Redis Cluster одновременно распределяет ключи между узлами и обеспечивает репликацию/failover.', ['Sentinel сам данные не хранит.', 'Cluster разбивает keyspace на 16384 hash slots.', 'Multi-key операции в Cluster проще, если ключи находятся в одном slot (hash tags).'])
  if (contains(q, 'hash slots')) return md('Hash slots в Redis Cluster', 'Redis Cluster делит keyspace на 16384 slots. Slot выбирается по CRC16 ключа modulo 16384 и назначается одному primary-узлу; при масштабировании slots переносятся между nodes.', ['Hash tags `{...}` позволяют поместить связанные ключи в один slot.', 'Клиент должен уметь обрабатывать MOVED/ASK redirects.', 'Шардирование повышает ёмкость, но усложняет операции по нескольким ключам.'])
  if (contains(q, 'distributed lock', 'redlock')) return md('Distributed lock и Redlock', 'Простейший корректный lock на одном Redis обычно берут командой `SET key token NX PX ttl`, а освобождают только если token всё ещё принадлежит клиенту. Redlock пытается получить lock на большинстве независимых Redis masters в ограниченное время.', ['TTL защищает от вечной блокировки.', 'Удалять lock простым `DEL` небезопасно: можно удалить чужой новый lock.', 'Для задач с жёсткими consistency guarantees дополнительно рассматривают fencing tokens и свойства конкретной инфраструктуры.'])
  if (contains(q, 'streams', 'consumer groups')) return md('Redis Streams и consumer groups', 'Redis Stream — append-only структура сообщений с ID. Consumer group позволяет нескольким consumer распределять обработку сообщений, сохраняя информацию о доставленных, но ещё не подтверждённых записях.', ['`XADD` добавляет сообщение, `XREADGROUP` читает в группе, `XACK` подтверждает обработку.', 'Pending Entries List помогает находить зависшие сообщения.', 'Streams подходят для очередей/event processing, но не полностью заменяют специализированный Kafka-подобный брокер во всех сценариях.'])
  if (contains(q, 'multi/exec', 'lua')) return md('MULTI/EXEC и Lua', '`MULTI` начинает очередь команд транзакции Redis, `EXEC` выполняет её последовательно без interleaving других клиентов. Это не классическая SQL-транзакция с автоматическим rollback. Lua script выполняется атомарно относительно других команд.', ['`WATCH` реализует optimistic locking.', 'Ошибка отдельной команды не означает rollback уже выполненных команд EXEC.', 'Lua полезен для атомарной read-modify-write логики, но долгий script блокирует event loop.'])
  if (contains(q, 'pipeline', 'maxmemory')) return md('Redis performance и memory', 'Pipelining отправляет несколько команд без ожидания ответа на каждую и сокращает network round trips. `maxmemory` ограничивает используемую память, а eviction policy определяет поведение при достижении лимита.', ['Избегайте огромных ключей и коллекций (big keys).', 'Выбирайте компактные структуры и TTL.', 'Используйте `SCAN` вместо блокирующего `KEYS` в production.', 'Измеряйте hit rate, latency, evictions и memory fragmentation.'])
  return md('Redis monitoring и modules', 'RedisInsight помогает исследовать данные, производительность и конфигурацию. Команды `INFO`, `SLOWLOG`, latency tools и системные метрики используются для мониторинга. Модули расширяют Redis специализированными структурами и поиском.', ['Следите за memory, evictions, hit rate, connected clients, replication lag, command latency.', 'Названия/доступность модулей зависят от используемой Redis distribution.'])
}

function clickElastic(q) {
  if (contains(q, 'партиционирование', 'sampling', 'ttl')) return md('ClickHouse: partitioning, ORDER BY, primary key, sampling, TTL', 'В MergeTree-семействе `ORDER BY` задаёт физический порядок данных и является главным фактором эффективности data skipping. Primary key задаёт sparse primary index и обычно является префиксом sorting key. `PARTITION BY` используют прежде всего для lifecycle/partition pruning, а TTL — для автоматического удаления/перемещения старых данных.', ['Не делайте слишком много мелких partitions.', 'Ставьте в начало ORDER BY поля, по которым часто фильтруют и которые хорошо соответствуют workload.', 'Sampling требует подходящего ключа/схемы и применим для приближённых аналитических запросов.'])
  if (contains(q, 'dictionary joins', 'distributed queries')) return md('ClickHouse dictionaries и distributed queries', 'Dictionary хранит внешние справочные данные в оптимизированной форме и может заменить часть JOIN-операций быстрым lookup. Distributed engine маршрутизирует запросы к shards, а затем объединяет частичные результаты.', ['Фильтруйте как можно раньше и читайте только нужные столбцы.', 'Выбирайте JOIN algorithm под размеры таблиц и память.', 'Materialized views могут переносить дорогую работу на ingest time.', 'Следите за количеством прочитанных rows/bytes, а не только за временем.'])
  if (contains(q, 'шарды и реплики')) return md('Elasticsearch shards и replicas', 'Elasticsearch делит index на primary shards; каждый shard является отдельным Lucene index. Replica — копия primary shard на другом узле, повышающая отказоустойчивость и capacity чтения.', ['Документ принадлежит одному primary shard.', 'Запись сначала обрабатывается primary и реплицируется.', 'Число primary shards задаётся при создании index и требует планирования; replicas можно менять.', 'Слишком много маленьких shards создают overhead.'])
  if (contains(q, 'refresh interval', 'translog')) return md('Refresh, translog, segments, fielddata и doc values', 'Elasticsearch/Lucene пишет данные в segments. Refresh делает новые изменения доступными поиску; translog помогает durability/recovery; background merges объединяют segments.', ['Увеличение refresh interval может ускорить массовую индексацию ценой свежести поиска.', 'Doc values — column-oriented representation на диске для sorting/aggregations большинства полей.', 'Fielddata для analyzed text может потреблять много heap и обычно избегается в пользу keyword/doc_values.'])
  if (contains(q, 'bulk api', 'reindex')) return md('Bulk и Reindex', 'Bulk API объединяет множество index/update/delete операций в один HTTP request и уменьшает сетевой overhead. Reindex копирует документы из source index в destination и применяется для изменения mappings/settings или миграции данных.', ['Подбирайте размер batch экспериментально: слишком большой bulk перегружает heap/queue.', 'Перед reindex заранее создайте destination с нужными mappings/settings.', 'Мониторьте rejected requests, indexing latency и merge pressure.'])
  return md('ILM, index templates и ingest pipelines', 'Index templates автоматически применяют settings/mappings к новым indices/data streams. Ingest pipeline преобразует документы до индексации. ILM автоматизирует lifecycle индекса: rollover и действия в hot/warm/cold/delete фазах в зависимости от политики.', ['Используйте data streams для типичных time-series/log workloads.', 'Тестируйте mappings до массовой загрузки.', 'Lifecycle должен соответствовать retention и стоимости хранения.'])
}

function architecture(q) {
  if (contains(q, 'circuit breaker, retry')) return md('Circuit Breaker и Retry', 'Retry повторяет временно неудачную операцию, а Circuit Breaker прекращает обращения к явно проблемной зависимости, чтобы не усиливать каскадный сбой.', ['Retry используйте только для ошибок, которые действительно могут исчезнуть.', 'Добавляйте exponential backoff + jitter и лимит попыток.', 'Circuit Breaker обычно имеет Closed/Open/Half-Open состояния.', 'Для неидемпотентных операций повтор требует idempotency strategy.'])
  if (contains(q, 'когда переходить')) return md('Когда переходить к микросервисам', 'Микросервисы оправданы, когда организационные и технические границы домена уже понятны, разные части системы требуют независимого масштабирования/релизов, а команда готова оплачивать сложность distributed systems.', ['Не начинайте с микросервисов только «ради масштабирования».', 'Нужны зрелые CI/CD, observability, ownership, API contracts и эксплуатация.', 'Часто хороший модульный монолит — лучший старт.', 'Граница сервиса должна отражать business capability/bounded context.'])
  if (contains(q, 'saga')) return md('Saga: Choreography vs Orchestration', 'Saga разбивает распределённую бизнес-транзакцию на локальные транзакции и компенсирующие действия. Choreography связывает шаги событиями без центрального координатора; Orchestration использует отдельный orchestrator, явно управляющий flow.', ['Choreography проще для коротких flows, но может стать трудно отслеживаемой сетью событий.', 'Orchestration делает процесс явным, но создаёт центральный компонент workflow.', 'Compensation — бизнес-действие, а не технический rollback общей БД.'])
  if (contains(q, 'eventual consistency')) return md('Eventual Consistency', 'При eventual consistency разные копии/сервисы могут временно видеть разные состояния, но при отсутствии новых изменений система стремится к согласованному результату.', ['Это компромисс ради availability/latency/decoupling.', 'UX должен учитывать временную несогласованность.', 'Нужны idempotency, повторная доставка, reconciliation и наблюдаемость.', 'Для критичных инвариантов иногда требуется сильная согласованность.'])
  if (contains(q, 'richardson', 'hateoas')) return md('REST maturity, HATEOAS и versioning', 'Richardson Maturity Model описывает эволюцию HTTP API: единый endpoint → ресурсы → корректное использование HTTP verbs/status → hypermedia controls (HATEOAS). Это модель зрелости, а не обязательный чек-лист.', ['HATEOAS передаёт клиенту доступные действия ссылками/отношениями.', 'Версионирование бывает в URL, headers/media types; важнее стабильный contract.', 'Старайтесь делать backward-compatible изменения и иметь deprecation policy.'])
  if (contains(q, 'kafka')) return md('Kafka: topic, partition, consumer group, offset, EOS', 'Topic разбит на partitions. Порядок гарантируется внутри конкретной partition. Consumer group распределяет partitions между consumer так, чтобы одну partition в группе обычно обрабатывал один consumer. Offset — позиция consumer в partition.', ['Ключ сообщения часто выбирает partition и помогает сохранить порядок по сущности.', 'At-least-once требует idempotent processing.', 'Kafka поддерживает idempotent producer и transactions для exactly-once processing в определённых Kafka-to-Kafka сценариях, но «exactly once end-to-end» зависит от всех внешних систем.'])
  if (contains(q, 'bulkhead', 'fallback')) return md('Retry, Bulkhead, Fallback', 'Retry повторяет временные ошибки; Bulkhead изолирует ресурсы, чтобы проблема одной зависимости не исчерпала всё; Fallback предоставляет деградированный результат при недоступности основного пути.', ['Комбинируйте с timeouts и circuit breaker.', 'Не retry-те validation/permission ошибки.', 'Bulkhead реализуют отдельными pools/queues/limits.', 'Fallback должен быть безопасным и явно наблюдаемым.'])
  if (contains(q, 'идемпотентность', 'outbox')) return md('Idempotency и Transactional Outbox', 'Идемпотентная операция даёт тот же бизнес-результат при повторном выполнении. Для HTTP-команд используют idempotency key. Transactional outbox сохраняет бизнес-изменение и событие outbox в одной локальной транзакции, после чего отдельный publisher доставляет событие.', ['Consumer всё равно стоит делать идемпотентным.', 'Outbox решает dual-write проблему между БД и broker.', 'Нужны уникальные ключи/deduplication и стратегия cleanup outbox.'])
  if (contains(q, 'distributed tracing', 'opentelemetry', 'istio')) return md('Distributed tracing, OpenTelemetry и service mesh', 'Distributed tracing связывает работу одного запроса через несколько сервисов в trace из spans. OpenTelemetry — vendor-neutral набор API/SDK/Collector и соглашений для traces, metrics и logs. Service mesh переносит часть сетевых функций между сервисами в инфраструктурный слой; Istio — один из вариантов.', ['Context propagation переносит trace/span context между процессами.', 'Sampling контролирует стоимость telemetry.', 'Mesh может дать mTLS, traffic policies и telemetry, но добавляет эксплуатационную сложность.'])
  return md('Backward compatibility и CQRS', 'Backward compatibility означает, что существующие клиенты продолжают работать после обновления API/событий. CQRS разделяет модели/пути команд (изменений) и запросов (чтения), когда их требования существенно различаются.', ['Добавляйте поля вместо удаления/переименования без миграции.', 'Для событий используйте schema evolution/versioning.', 'CQRS не требует обязательного event sourcing.', 'Не применяйте CQRS там, где обычная CRUD-модель проще и достаточна.'])
}

function docker(q) {
  if (contains(q, 'multi-stage')) return md('Multi-stage build', 'Multi-stage Dockerfile использует несколько `FROM`: в build stage устанавливаются компиляторы и зависимости, а в финальный runtime image копируется только готовый artifact. Это уменьшает размер образа и attack surface.', ['Используйте небольшой подходящий runtime base image.', 'Копируйте только необходимые artifacts.', 'Закрепляйте версии и используйте BuildKit cache mounts там, где это уместно.'], '```dockerfile\nFROM node:22 AS build\nWORKDIR /app\nCOPY . .\nRUN npm ci && npm run build\n\nFROM nginx:alpine\nCOPY --from=build /app/dist /usr/share/nginx/html\n```')
  if (contains(q, 'bridge', 'host', 'overlay')) return md('Docker networks', 'Bridge — стандартная сеть одного Docker host с изоляцией и DNS по именам контейнеров в user-defined network. Host отключает отдельный network namespace контейнера и использует сеть host. Overlay соединяет контейнеры/сервисы на нескольких Docker hosts (например, Swarm).', ['Для Compose сервисы в одной сети обращаются друг к другу по service name.', 'Публикация порта (`-p`) нужна для доступа извне Docker network, а не для общения контейнеров внутри неё.'])
  if (contains(q, 'volumes vs bind')) return md('Volumes vs Bind mounts', 'Volume управляется Docker и хранится в Docker storage; bind mount монтирует конкретный путь host в контейнер.', ['Volumes удобнее и переносимее для persistent application data.', 'Bind mount полезен в development для исходников/configs.', 'Bind mount сильнее связывает контейнер с файловой системой host.', 'Не храните важные данные только в writable container layer.'])
  if (contains(q, 'docker secrets', 'swarm', 'kubernetes')) return md('Secrets и orchestration', 'Docker secrets предназначены для передачи секретов сервисам Swarm без упаковки секрета в image. Docker Swarm и Kubernetes оркестрируют контейнерные workloads: scheduling, service discovery, rollout, health и масштабирование.', ['Не кладите секреты в Dockerfile/ENV при build, если они попадут в layers/history.', 'В Kubernetes secrets требуют корректной RBAC/encryption strategy.', 'Kubernetes богаче экосистемой и функциональностью, но сложнее в эксплуатации.'])
  if (contains(q, 'docker hub', 'private registry', 'profiles')) return md('Registry и Compose profiles', 'Registry хранит и раздаёт container images. Docker Hub — публичный/managed registry, private registry ограничивает доступ внутри организации. Compose profiles позволяют включать опциональные сервисы для конкретных режимов запуска.', ['Тег `latest` не является гарантией неизменности — в production лучше immutable tags/digests.', 'Настройте scanning, auth и retention.', 'Profiles удобны для debug/admin tooling, которое не нужно всегда.'])
  if (contains(q, 'healthcheck', 'restart policies')) return md('Healthcheck, restart policy и resource limits', 'HEALTHCHECK проверяет не просто наличие процесса, а способность контейнера обслуживать работу. Restart policy определяет перезапуск после завершения. CPU/memory limits защищают host и соседние workloads от одного контейнера.', ['Healthcheck должен быть дешёвым и отражать реальную готовность.', 'OOM из-за memory limit нужно наблюдать.', 'Не используйте бесконечный restart как замену устранению root cause.'])
  if (contains(q, 'non-root', 'buildkit', '.dockerignore')) return md('Docker security и build optimization', 'Запускайте процесс от non-root user, минимизируйте base image и установленные пакеты, сканируйте image и зависимости, не храните secrets в layers. BuildKit улучшает build cache и поддерживает безопасные secret/cache mounts.', ['`.dockerignore` уменьшает build context и риск случайно скопировать секреты.', 'Используйте multi-stage build.', 'Закрепляйте base image version/digest по требованиям supply-chain.', 'Rootless Docker снижает часть рисков daemon/container privileges.'])
  return md('Docker contexts, Desktop, rootless и DinD', 'Docker context хранит параметры подключения к конкретному daemon/endpoint. Docker Desktop предоставляет локальную VM/интеграцию для macOS/Windows и dev tools. Rootless mode запускает daemon/containers без root privileges host. DinD запускает Docker daemon внутри контейнера.', ['DinD нужен не всегда: в CI часто безопаснее dedicated builders/BuildKit.', 'Mount docker.sock фактически даёт очень широкие права на host Docker daemon.', 'Выбирайте подход, учитывая isolation и security model.'])
}

function cicd(q) {
  if (contains(q, 'кэширование зависимостей')) return md('Кэширование dependencies в CI', 'Dependency cache сохраняет скачанные пакеты/артефакты между запусками pipeline и уменьшает время установки. Cache key должен зависеть от lock-file, OS/runtime и других факторов совместимости.', ['Cache — оптимизация, а не источник истины; pipeline должен уметь восстановиться при cache miss.', 'Не кэшируйте секреты.', 'Различайте dependency cache и build artifacts.'])
  if (contains(q, 'rolling', 'blue-green', 'canary')) return md('Rolling, Blue-Green и Canary', 'Rolling постепенно заменяет экземпляры старой версии. Blue-Green держит две полноценные среды и переключает traffic. Canary сначала отправляет небольшой процент traffic на новую версию и расширяет rollout после проверки.', ['Rolling экономичен, но некоторое время версии сосуществуют.', 'Blue-Green даёт быстрый rollback ценой ресурсов.', 'Canary снижает blast radius, но требует метрик и traffic control.'])
  if (contains(q, 'gitops', 'argocd', 'flux')) return md('Secrets и GitOps', 'GitOps хранит желаемое состояние инфраструктуры/приложений в Git, а agent/controller (например Argo CD или Flux) синхронизирует runtime с репозиторием.', ['Секреты нельзя хранить в Git открытым текстом; используют secret managers или encrypted/sealed secrets.', 'Git history даёт audit trail и rollback желаемого состояния.', 'Разделяйте app config и secret material.'])
  if (contains(q, 'infrastructure as code')) return md('Infrastructure as Code', 'IaC описывает инфраструктуру декларативным или автоматизированным кодом, чтобы окружения были воспроизводимыми и ревьюились как обычные изменения.', ['Terraform управляет ресурсами providers через state.', 'Ansible чаще применяют для configuration management/procedural automation.', 'Helm шаблонизирует Kubernetes resources.', 'Kubernetes manifests описывают desired state объектов cluster.'])
  if (contains(q, 'feature flags', 'progressive delivery')) return md('Feature flags и progressive delivery', 'Feature flag отделяет deploy кода от release функциональности. Progressive delivery постепенно расширяет аудиторию новой версии/фичи на основе метрик и правил; automated rollback возвращает безопасную версию при деградации.', ['У флагов должен быть owner и срок удаления.', 'Не делайте security boundary только через client-side flag.', 'Rollback должен учитывать миграции данных и backward compatibility.'])
  if (contains(q, 'pipeline optimization')) return md('Оптимизация pipeline', 'Pipeline ускоряют параллельным выполнением независимых jobs, кэшированием, запуском только затронутых проверок и правильным разделением быстрых feedback stages и дорогих stages.', ['Approval gates нужны там, где требуется контроль риска/compliance.', 'Manual/scheduled triggers не должны обходить обязательные security checks.', 'Собирайте метрики duration, queue time, failure rate и flaky jobs.'])
  return md('Pipeline templates и security', 'Templates/shared libraries уменьшают копирование CI-конфигурации и централизуют стандартные build/test/deploy практики. Их нужно версионировать, потому что изменение общей библиотеки способно затронуть много проектов.', ['Минимизируйте permissions CI token.', 'Pin сторонние actions/images по доверенным версиям/digest.', 'Не выводите secrets в logs.', 'Разделяйте untrusted PR code и privileged deployment jobs.'])
}

function monitoring(q) {
  if (contains(q, 'metrics vs logs vs traces')) return md('Metrics, Logs, Traces', 'Metrics — агрегированные числовые временные ряды; logs — дискретные записи событий; traces — путь одного запроса через компоненты/сервисы.', ['Metrics хорошо отвечают «есть ли проблема и насколько она массовая».', 'Logs дают подробный контекст событий.', 'Traces показывают где конкретный запрос потратил время/сломался.', 'Общие correlation/trace IDs связывают сигналы.'])
  if (contains(q, 'prometheus + grafana', 'pull')) return md('Prometheus + Grafana', 'Prometheus регулярно scrapes HTTP endpoints с метриками по pull-модели и сохраняет time series. Grafana запрашивает Prometheus и строит dashboards. Alert rules обычно оцениваются Prometheus, а Alertmanager маршрутизирует alerts.', ['Pull упрощает discovery/health наблюдение target-ов.', 'Для short-lived jobs используют специальные паттерны вроде Pushgateway только когда это действительно оправдано.', 'Контролируйте cardinality labels.'])
  if (contains(q, 'метрики мониторить для java')) return md('Java/JVM metrics', 'Для Java-приложения важны системные, JVM и бизнес-метрики одновременно.', ['Heap/non-heap usage и allocation rate.', 'GC pause time/frequency.', 'Thread count, blocked/deadlocked threads.', 'CPU, process memory, file descriptors.', 'HTTP RPS/error rate/latency, connection pools, queue depth.', 'Бизнес-SLI: успешные операции, latency критичных flows.'])
  if (contains(q, 'sli', 'slo', 'sla')) return md('SLI, SLO, SLA и observability', 'SLI — измеряемый показатель качества (например доля успешных requests). SLO — целевое значение SLI за окно времени. SLA — внешнее соглашение, часто с последствиями при нарушении. Observability — способность понимать внутреннее состояние системы по её сигналам.', ['SLO должен отражать пользовательский опыт.', '100% SLO обычно слишком дорого и мешает изменениям.', 'Error budget = допустимая доля неуспеха относительно SLO.'])
  if (contains(q, 'jaeger', 'zipkin', 'opentelemetry')) return md('Distributed tracing', 'Trace состоит из spans, представляющих операции одного distributed request. Trace context передаётся через сетевые границы. Jaeger/Zipkin — trace backends, OpenTelemetry стандартизирует instrumentation и сбор telemetry.', ['Не забывайте context propagation в async/message flows.', 'Sampling контролирует объём данных.', 'Span attributes/events должны помогать диагностике, но не утекать PII/secrets.'])
  if (contains(q, 'structured logging', 'loki')) return md('Structured logging и aggregation', 'Structured logs записывают поля в машиночитаемом формате (часто JSON), а не только текст. ELK/OpenSearch-подобный стек или Loki централизуют поиск и корреляцию logs.', ['Поля: timestamp, level, service, environment, request/trace ID.', 'Не логируйте пароли/tokens/персональные данные без необходимости.', 'Log rotation/retention защищают диск и бюджет.', 'Cardinality и объём logs также требуют контроля.'])
  if (contains(q, 'alert routing', 'silencing')) return md('Alert routing и on-call', 'Alertmanager-подобная система группирует похожие alerts, маршрутизирует их нужной команде, поддерживает inhibit/silence и интеграции с on-call каналами.', ['Alert должен быть actionable.', 'Группировка снижает alert storm.', 'Silence применяют осознанно и ограниченно по времени.', 'У alert должны быть severity, owner и runbook.'])
  if (contains(q, 'incident management', 'post-mortem')) return md('Incident management и error budget', 'Incident management включает обнаружение, triage, mitigation, communication и восстановление. После серьёзного инцидента проводят blameless post-mortem: timeline, impact, contributing factors и конкретные action items.', ['Error budget связывает reliability и скорость изменений.', 'Во время incident сначала стабилизируют сервис, затем ищут глубокую причину.', 'Action items должны иметь owner и срок.'])
  return md('Availability и synthetic monitoring', 'Availability monitoring проверяет доступность реальных компонентов/endpoint-ов. Synthetic monitoring регулярно выполняет искусственные проверки или пользовательские сценарии из контролируемых locations.', ['Synthetic checks находят проблему даже при отсутствии реального traffic.', 'Проверяйте не только HTTP 200, но и критический бизнес-результат.', 'Сочетайте с real-user monitoring для реального client experience.'])
}

function gitAnswer(q) {
  if (contains(q, 'tag, branch, remote, origin')) return md('Git: tag, branch, remote, origin', 'Branch — подвижный указатель на commit; tag обычно фиксирует конкретный commit (например release). Remote — сохранённое имя удалённого repository URL, а `origin` — стандартное имя remote, которое `git clone` создаёт по умолчанию.', ['`git branch` управляет ветками.', '`git tag` создаёт/просматривает теги.', '`git remote -v` показывает remotes.', '`origin` — соглашение, его можно переименовать или иметь несколько remotes.'])
  if (contains(q, 'merge vs rebase')) return md('Merge vs Rebase', 'Merge создаёт объединение histories (часто merge commit) и сохраняет исходное ветвление. Rebase переносит commits на новую базу, переписывая их hashes и создавая линейную историю.', ['Не rebase-те опубликованную shared history без договорённости.', 'Merge безопаснее сохраняет реальную topology.', 'Rebase удобен для очистки локальной feature branch перед merge.', 'После rebase push обычно требует `--force-with-lease`, а не грубый `--force`.'])
  if (contains(q, 'cherry-pick')) return md('Cherry-pick и конфликты', '`git cherry-pick <commit>` применяет изменения выбранного commit поверх текущей ветки как новый commit. При конфликте Git останавливается: исправляют файлы, `git add`, затем `git cherry-pick --continue` или `--abort`.', ['Cherry-pick удобен для backport/hotfix, но массовое использование может дублировать history.', 'При сложных конфликтах сначала поймите намерение обеих сторон, а не только добейтесь отсутствия conflict markers.'])
  if (contains(q, 'git flow', 'trunk-based')) return md('Git Flow vs Trunk-Based Development', 'Git Flow использует долгоживущие ветки develop/release/hotfix и подходит процессам с формальными release cycles. Trunk-Based Development держит основную ветку всегда интегрируемой и использует короткоживущие branches, частые merges и feature flags.', ['Trunk-based хорошо сочетается с CI/CD.', 'Долгоживущие branches увеличивают integration risk.', 'Выбор зависит от release/process constraints, а не моды.'])
  if (contains(q, 'hooks', 'conventional commits')) return md('Git hooks, Conventional Commits, SemVer', 'Git hooks запускают локальные скрипты на события вроде pre-commit/pre-push. Conventional Commits задаёт формат сообщения (`feat:`, `fix:` и т.п.), который можно использовать для changelog/release automation. SemVer использует MAJOR.MINOR.PATCH.', ['Локальные hooks не являются security boundary — проверки дублируйте в CI.', 'Breaking change повышает MAJOR, новая backward-compatible feature — MINOR, fix — PATCH.', 'Инструменты типа lint-staged ускоряют pre-commit проверки.'])
  if (contains(q, 'bisect', 'reflog', 'worktree')) return md('bisect, reflog, stash, worktree', '`git bisect` бинарным поиском находит commit, внёсший регрессию. `reflog` хранит локальную историю перемещения refs и помогает восстановить «потерянный» commit. `stash` временно откладывает изменения. `worktree` позволяет checkout нескольких веток в разных директориях одного repo.', ['`stash pop` применяет и удаляет stash при успехе; `apply` не удаляет.', 'Reflog локален и имеет срок хранения.', 'Bisect можно автоматизировать тестовой командой.'])
  if (contains(q, 'submodule', 'subtree', 'lfs')) return md('Submodule, subtree, LFS, sparse/shallow', 'Submodule хранит ссылку на commit другого repository. Subtree встраивает чужую history/содержимое в основной repo. Git LFS заменяет большие binary files pointer-ами. Sparse checkout получает рабочее дерево частично, shallow clone ограничивает depth истории.', ['Submodule требует явного управления версиями вложенного repo.', 'LFS требует server support/storage quota.', 'Shallow clone полезен CI, но часть history-based операций ограничена.'])
  return md('Git diagnostics и maintenance', '`git blame` показывает commit/автора строк, `log --graph` визуализирует history, `diff` сравнивает изменения, `show` показывает объект/commit. `clean` удаляет untracked files, `gc` оптимизирует repository, `fsck` проверяет целостность объектов.', ['`git clean -n` сначала показывает, что будет удалено.', '`blame` — инструмент исследования истории, не поиска виноватых.', '`reflog` часто полезнее `fsck` для восстановления после ошибочного reset/rebase.'])
}

function review(q) {
  if (contains(q, 'несогласии', 'constructive feedback')) return md('Несогласие на code review', 'Обсуждайте не человека, а риск/требование/код. Сначала уточните, какую проблему пытается решить комментарий, затем приведите факты: требования, benchmark, style guide, тест или минимальный пример.', ['Не превращайте review в соревнование за правоту.', 'Если есть несколько нормальных решений — договоритесь о командном convention.', 'Для затяжного спора быстрее перейти в короткий call и зафиксировать решение.', 'Эскалируйте только когда затронуты существенные risk/security/architecture вопросы.'])
  if (contains(q, 'sonarqube', 'eslint')) return md('Автоматизация review', 'Статические анализаторы и formatter-ы должны автоматически проверять то, что машина проверяет лучше человека: style, часть bugs/security smells, форматирование и базовые quality gates.', ['ESLint/Checkstyle — статические правила языка/стиля.', 'Prettier — детерминированное форматирование.', 'SonarQube агрегирует quality/security findings и метрики.', 'Автоматизация не заменяет review бизнес-логики и архитектуры.'])
  if (contains(q, 'cyclomatic', 'coverage')) return md('Complexity и coverage', 'Cyclomatic complexity приблизительно отражает число независимых путей выполнения и растёт с ветвлениями. Code coverage показывает, какая часть кода была выполнена тестами, но не доказывает качество assertions.', ['Высокая сложность — сигнал рассмотреть декомпозицию, а не абсолютный запрет.', '100% coverage может сосуществовать с плохими тестами.', 'Смотрите branch coverage и risk-critical paths, а не только line percentage.'])
  if (contains(q, 'виды ревью')) return md('Фокусы code review', 'Один review может проверять несколько измерений: корректность, security, performance, accessibility, tests, documentation, API compatibility, database/infrastructure changes.', ['Security: auth, validation, secrets, injection.', 'Performance: алгоритмы, I/O, N+1, allocations.', 'A11y: semantics, keyboard, labels, contrast.', 'DB/API: migrations, backward compatibility, rollback.', 'Tests/docs: критические сценарии и понятный operational context.'])
  if (contains(q, 'owasp')) return md('Security review и OWASP Top 10', 'Security review ищет классы рисков вроде broken access control, injection, cryptographic failures, insecure design/misconfiguration и vulnerable dependencies. OWASP Top 10 — ориентир по распространённым рискам, а не полный чек-лист безопасности.', ['Проверяйте authorization на server side.', 'Валидируйте input и используйте parameterized queries.', 'Не храните secrets в source/logs.', 'Обновляйте dependencies и включайте SAST/DAST/dependency scanning по риску.'])
  if (contains(q, 'anti-patterns', 'review fatigue')) return md('Code review anti-patterns', 'Плохие паттерны: огромные PR, вкусовщина без правила, nitpicking вручную вместо lint, задержка review на дни, «LGTM» без чтения, агрессивная коммуникация и попытка перепроектировать весь проект в одном PR.', ['Делайте PR небольшими и сфокусированными.', 'Автоматизируйте mechanical checks.', 'Определите ожидаемый turnaround time.', 'Для сложного изменения приложите context/ADR/скриншоты/план тестирования.'])
  return md('Egoless programming и growth mindset', 'Egoless programming отделяет самооценку разработчика от конкретного решения в коде: любой код можно улучшить, а review — совместная работа над качеством. Growth mindset воспринимает feedback как источник обучения.', ['Критикуйте код/риск, а не автора.', 'Объясняйте «почему», особенно менее опытным коллегам.', 'Умейте менять мнение при появлении данных.', 'Хвалите хорошие решения так же конкретно, как указываете проблемы.'])
}

function network(q) {
  if (contains(q, '3-way handshake', 'нейгла')) return md('TCP handshake, Nagle и TCP_NODELAY', 'TCP-соединение обычно устанавливается обменом SYN → SYN-ACK → ACK. Алгоритм Nagle уменьшает число маленьких сегментов, задерживая часть отправок до ACK/накопления данных. `TCP_NODELAY` отключает Nagle, что полезно для некоторых latency-sensitive протоколов.', ['TCP_NODELAY не нужно включать автоматически без измерений.', 'Nagle может плохо взаимодействовать с delayed ACK в чатty протоколах.', 'Handshake согласует начальные sequence numbers и состояние соединения.'])
  if (contains(q, 'slow start', 'fast retransmit')) return md('TCP congestion control', 'Receiver window ограничивает отправителя возможностями получателя (flow control), а congestion window — оценкой пропускной способности сети. Slow start быстро увеличивает окно до порога/признаков congestion, после чего рост становится осторожнее.', ['Fast retransmit реагирует на duplicate ACK и повторно отправляет вероятно потерянный segment до timeout.', 'Fast recovery избегает полного возврата к начальному состоянию после отдельных потерь.', 'Конкретные congestion-control algorithms могут отличаться от классической схемы.'])
  if (contains(q, 'mtu', 'arp', 'icmp', 'dhcp')) return md('MTU, fragmentation, TTL, ARP, ICMP, DHCP', 'MTU — максимальный размер network-layer packet для канала без fragmentation. IP TTL/Hop Limit ограничивает число hops. ARP в IPv4 связывает IP с MAC в локальной сети. ICMP несёт диагностические/control сообщения. DHCP автоматически выдаёт сетевые параметры клиенту.', ['IPv6 использует Neighbor Discovery вместо ARP.', 'Path MTU Discovery помогает избежать fragmentation.', 'BOOTP — более старый протокол, предшественник DHCP.'])
  if (contains(q, 'keep-alive', 'half-open', 'fin')) return md('TCP connection states', 'Нормальное закрытие TCP использует FIN/ACK в каждом направлении, потому что потоки полудуплексно закрываются независимо. RST аварийно сбрасывает connection. Half-open возникает, когда стороны имеют несовпадающее представление о состоянии соединения.', ['TCP keepalive периодически проверяет долго простаивающее соединение по настройкам ОС.', 'Application-level heartbeat часто даёт более предсказуемое обнаружение проблем.', 'TCP state machine включает LISTEN, SYN_SENT/RECEIVED, ESTABLISHED, FIN_WAIT, CLOSE_WAIT, TIME_WAIT и др.'])
  return md('TIME_WAIT, CLOSE_WAIT, SYN flood и DDoS', '`TIME_WAIT` обычно остаётся у стороны активного закрытия, чтобы старые сегменты не попали в новое соединение и можно было повторно подтвердить FIN. `CLOSE_WAIT` означает: peer прислал FIN, а локальное приложение ещё не закрыло socket.', ['Много CLOSE_WAIT часто указывает на bug/утечку соединений в приложении.', 'SYN flood истощает ресурсы полуоткрытых соединений; защиты включают SYN cookies, rate limiting и upstream mitigation.', 'DDoS шире SYN flood и требует многоуровневой защиты/CDN/scrubbing.'])
}

function http(q) {
  if (contains(q, 'https, cors, rest')) return md('HTTPS, CORS и REST', 'HTTPS — HTTP поверх TLS, обеспечивающий шифрование канала и проверку подлинности сервера сертификатом. CORS — браузерный механизм, который регулирует чтение cross-origin ответов frontend-кодом. REST — архитектурный стиль ресурсного HTTP API.', ['CORS не является механизмом серверной авторизации.', 'TLS защищает транспорт, но не исправляет XSS/SQL injection.', 'REST обычно использует ресурсы, HTTP methods/status codes и stateless requests.'])
  if (contains(q, 'preflight')) return md('CORS Preflight', 'Для некоторых cross-origin запросов браузер сначала отправляет `OPTIONS` preflight, чтобы спросить сервер, разрешены ли origin, method и headers. Если ответ содержит подходящие `Access-Control-Allow-*`, браузер отправляет основной запрос.', ['Simple requests могут обходиться без preflight.', '`Access-Control-Allow-Origin` должен соответствовать политике сервера.', 'Credentials требуют явного origin и `Access-Control-Allow-Credentials: true`.'])
  if (contains(q, 'cache-control', 'etag', 'last-modified')) return md('HTTP caching', '`Cache-Control` задаёт правила freshness/storage (`max-age`, `no-store`, `private`, `public` и др.). ETag — validator версии представления; клиент может отправить `If-None-Match`. Last-Modified работает с `If-Modified-Since` как более простой validator.', ['При валидном кэше сервер может ответить `304 Not Modified` без body.', 'Для versioned static assets часто используют долгий `max-age` + `immutable`.', '`no-cache` означает «проверять перед использованием», а не «никогда не хранить»; для запрета хранения есть `no-store`.'])
  if (contains(q, 'httponly', 'samesite')) return md('Cookie security attributes', '`HttpOnly` запрещает JavaScript доступ к cookie, снижая риск кражи через XSS. `Secure` отправляет cookie только по HTTPS. `SameSite` ограничивает отправку cookie в cross-site контексте и помогает снижать CSRF.', ['`SameSite=Strict` наиболее жёсткий, `Lax` часто разумный default, `None` требует `Secure`.', 'Cookie всё равно должен иметь минимальные Domain/Path/Max-Age и server-side validation.'])
  if (contains(q, 'xss', 'csrf')) return md('XSS и CSRF', 'XSS заставляет страницу выполнить атакующий script/markup в контексте сайта; основная защита — контекстное escaping/encoding, безопасный DOM API, sanitization для разрешённого HTML и CSP как дополнительный слой. CSRF заставляет browser жертвы отправить авторизованный request на другой сайт.', ['Для CSRF используют SameSite cookies, anti-CSRF tokens и проверку Origin/Referer по модели приложения.', 'HttpOnly защищает cookie от чтения JS, но сам не предотвращает XSS.', 'Никогда не вставляйте непроверенный input через `innerHTML`/`v-html`.'])
  if (contains(q, 'tls handshake', 'hsts')) return md('HTTPS и TLS', 'TLS handshake согласует версию/шифросuites, проверяет сертификат сервера и создаёт общие session keys. Асимметричная криптография нужна для аутентификации/обмена ключевым материалом, а bulk traffic шифруется быстрыми симметричными алгоритмами.', ['Сертификат связывает public key с доменом через доверенную CA; Let’s Encrypt автоматизирует выдачу сертификатов.', 'HSTS сообщает браузеру использовать HTTPS для домена в течение заданного времени.', 'Современный TLS 1.3 сокращает handshake и убирает устаревшие алгоритмы.'])
  if (contains(q, 'http/2', 'http/3')) return md('HTTP/2 и HTTP/3', 'HTTP/2 мультиплексирует несколько streams поверх одного TCP connection и использует HPACK header compression. HTTP/3 переносит HTTP semantics на QUIC поверх UDP; QUIC включает TLS 1.3 и устраняет TCP head-of-line blocking между независимыми streams.', ['HTTP/2 server push существовал как функция протокола, но браузерная поддержка практически ушла; не следует строить современную оптимизацию вокруг него.', 'HTTP/3 использует QPACK для header compression.', 'Оба протокола сохраняют привычные HTTP methods/status/headers на уровне semantics.'])
  if (contains(q, 'websocket', 'sse', 'long polling')) return md('WebSocket, SSE и long polling', 'WebSocket создаёт постоянный двунаправленный канал. SSE держит HTTP response открытым и передаёт события server→client. Long polling держит request до появления события, затем клиент создаёт новый request.', ['WebSocket удобен для частого bidirectional realtime traffic.', 'SSE проще для однонаправленных notifications и автоматически переподключается в EventSource.', 'Long polling работает почти везде, но создаёт больше HTTP overhead.'])
  return md('REST vs GraphQL vs gRPC', 'REST моделирует ресурсы через HTTP endpoints. GraphQL даёт типизированную query language, где клиент выбирает поля. gRPC использует RPC-контракты (обычно Protocol Buffers) и эффективный бинарный HTTP/2 transport.', ['REST прост и хорошо дружит с HTTP caching/tools.', 'GraphQL снижает over/under-fetching, но требует контроля complexity/caching/auth.', 'gRPC силён во внутренних service-to-service API и streaming, но browser integration отличается от обычного REST.', 'Выбор зависит от клиентов, latency, schema evolution и operational tooling.'])
}

function genericFull(topicId, title) {
  if (topicId === 4) return pinia(title)
  if (topicId === 11) return nodeAnswer(title)
  if (topicId === 12) return sql(title)
  if (topicId === 13) return postgres(title)
  if (topicId === 14) return redis(title)
  if (topicId === 15) return clickElastic(title)
  if (topicId === 16) return architecture(title)
  if (topicId === 17) return docker(title)
  if (topicId === 18) return cicd(title)
  if (topicId === 19) return monitoring(title)
  if (topicId === 20) return gitAnswer(title)
  if (topicId === 21) return review(title)
  if (topicId === 22) return network(title)
  if (topicId === 23) return http(title)
  return md(title, `Подробный ответ на вопрос «${title}». Проверьте этот вопрос вручную: для него не нашлось специализированного шаблона.`, ['Определите основное понятие.', 'Назовите ключевые свойства и trade-offs.', 'Приведите практический пример.'])
}

// Matches generated question object fields. The migration format uses template literals.
const QUESTION_RE = /(\{\s*"id":\s*`((?:\\`|[^`])*)`,\s*"title":\s*`((?:\\`|[^`])*)`,\s*"fullAnswer":\s*`)((?:\\`|[^`])*)(`,\s*"shortAnswer":\s*`)((?:\\`|[^`])*)(`,\s*\})/gs

let changedFiles = 0
let filledFull = 0
let filledShort = 0
let totalQuestions = 0
const unresolved = []

for (let topicId = 1; topicId <= 23; topicId++) {
  const file = path.join(QUESTIONS_DIR, `topic-${topicId}.ts`)
  if (!fs.existsSync(file)) {
    console.warn(`⚠️ Нет файла: ${file}`)
    continue
  }

  const original = fs.readFileSync(file, 'utf8')
  let localFull = 0
  let localShort = 0

  const updated = original.replace(QUESTION_RE, (_m, prefix, id, rawTitle, rawFull, mid, rawShort, suffix) => {
    totalQuestions++
    const title = rawTitle.replace(/\\`/g, '`').replace(/\\\$\{/g, '${').replace(/\\\\/g, '\\')
    let full = rawFull.replace(/\\`/g, '`').replace(/\\\$\{/g, '${').replace(/\\\\/g, '\\')
    let short = rawShort.replace(/\\`/g, '`').replace(/\\\$\{/g, '${').replace(/\\\\/g, '\\')

    if (!full.trim() || full.trim() === FULL_PLACEHOLDER) {
      full = genericFull(topicId, title)
      localFull++
      filledFull++
    }

    if (!short.trim() || short.trim() === SHORT_PLACEHOLDER) {
      short = sentenceShort(full, title)
      localShort++
      filledShort++
    }

    if (!full.trim() || full.includes(FULL_PLACEHOLDER) || !short.trim() || short.includes(SHORT_PLACEHOLDER)) {
      unresolved.push({ topicId, id, title })
    }

    return `${prefix}${esc(full)}${mid}${esc(short)}${suffix}`
  })

  if (updated !== original) {
    const backup = `${file}.bak`
    if (!fs.existsSync(backup)) fs.writeFileSync(backup, original, 'utf8')
    fs.writeFileSync(file, updated, 'utf8')
    changedFiles++
  }

  console.log(`topic-${topicId}.ts: full +${localFull}, short +${localShort}`)
}

console.log('\n=== Итог ===')
console.log(`Вопросов обработано: ${totalQuestions}`)
console.log(`Файлов изменено: ${changedFiles}`)
console.log(`Подробных ответов добавлено: ${filledFull}`)
console.log(`Кратких ответов добавлено: ${filledShort}`)
console.log(`Нерешённых заглушек: ${unresolved.length}`)

if (unresolved.length) {
  console.log(JSON.stringify(unresolved, null, 2))
  process.exitCode = 1
} else {
  console.log('✅ Все вопросы имеют fullAnswer и shortAnswer.')
}
